; The Outsider - intro (1989), coding Dr.Maurice, graphics Vincent
; Relocatable rebuild of the unpacked image originally loaded at $32250.
; - no ORG: every absolute address is a label, bitplane pointers in the
;   copper list are filled at runtime by FixCopper
; - removed: credits checksum + memory wipe, runtime decryption
;   (SUBI #$1532 / SUBI #$7f8f, data stored already decrypted), copy of the
;   gfx block $467e0->$5e000, unused copy/decrunch routines,
;   self-modifying code (song speed, JMP to old level 3 vector)

EXT_0000	EQU	$4
