; Fill the high/low words of the bitplane pointers in the copper list
FixCopper:
	LEA	CopHiTab(PC),A0
.hi:	MOVE.L	(A0)+,D0
	BEQ.S	.lo0
	MOVEA.L	D0,A1
	MOVE.L	(A0)+,D0
	SWAP	D0
	MOVE.W	D0,2(A1)
	BRA.S	.hi
.lo0:	LEA	CopLoTab(PC),A0
.lo:	MOVE.L	(A0)+,D0
	BEQ.S	.done
	MOVEA.L	D0,A1
	MOVE.L	(A0)+,D0
	MOVE.W	D0,2(A1)
	BRA.S	.lo
.done:	RTS

CopHiTab:
	DC.L	CopLogoH1,Logo
	DC.L	CopLogoH2,Logo+$cd0
	DC.L	CopLogoH3,Logo+$19a0
	DC.L	CopLogoH4,Logo+$2670
