LAB_00A1:
	DC.W	$0180,$0000		;5effc
; AGA/ECS (A1200/A600): the OS copper may leave a 64 bit fetch mode, its own
; BPLCON3 and display window: restore OCS-compatible values (FMODE, BPLCON3
; and DIWHIGH are no-op registers on OCS)
	DC.W	$01fc,$0000		; FMODE
	DC.W	$0106,$0c00		; BPLCON3
; KS3.1 copinit rewrites DIWSTRT/DIWSTOP every frame: set the display window
; before line $2c (the intro only does it at line $60, too late on AGA)
	DC.W	$008e,$2c80		; DIWSTRT
	DC.W	$0090,$2cd0		; DIWSTOP
	DC.W	$01e4,$2100		; DIWHIGH
